class Solution:
    def minimumCost(self, nums):
        import bisect
        pals = []
        for h in range(1, 100000):
            s = str(h)
            for t in (s + s[::-1], s + s[-2::-1]):
                p = int(t)
                if p < 10 ** 9:
                    pals.append(p)
        pals = sorted(set(pals))
        nums.sort()
        m = nums[len(nums) // 2]
        i = bisect.bisect_left(pals, m)
        best = float('inf')
        for p in pals[max(0, i - 2): i + 2]:
            best = min(best, sum(abs(x - p) for x in nums))
        return best

