class Solution {
public:
    long long minimumCost(vector<int>& nums) {
        vector<long long> pals;
        for (long long h = 1; h < 100000; h++) {
            string s = to_string(h), r(s.rbegin(), s.rend());
            long long p1 = stoll(s + r), p2 = stoll(s + r.substr(1));
            if (p1 < 1e9) pals.push_back(p1);
            if (p2 < 1e9) pals.push_back(p2);
        }
        sort(pals.begin(), pals.end());
        pals.erase(unique(pals.begin(), pals.end()), pals.end());
        sort(nums.begin(), nums.end());
        long long m = nums[nums.size() / 2];
        int i = lower_bound(pals.begin(), pals.end(), m) - pals.begin();
        long long best = LLONG_MAX;
        for (int k = max(0, i - 2); k < min((int)pals.size(), i + 2); k++) {
            long long c = 0;
            for (int x : nums) c += llabs(x - pals[k]);
            best = min(best, c);
        }
        return best;
    }
};

