class Solution {
    public long minimumCost(int[] nums) {
        TreeSet<Long> set = new TreeSet<>();
        for (long h = 1; h < 100000; h++) {
            String s = Long.toString(h);
            String r = new StringBuilder(s).reverse().toString();
            long p1 = Long.parseLong(s + r), p2 = Long.parseLong(s + r.substring(1));
            if (p1 < 1e9) set.add(p1);
            if (p2 < 1e9) set.add(p2);
        }
        List<Long> pals = new ArrayList<>(set);
        Arrays.sort(nums);
        long m = nums[nums.length / 2];
        int i = Collections.binarySearch(pals, m);
        if (i < 0) i = -(i + 1);
        long best = Long.MAX_VALUE;
        for (int k = Math.max(0, i - 2); k < Math.min(pals.size(), i + 2); k++) {
            long c = 0;
            for (int x : nums) c += Math.abs((long) x - pals.get(k));
            best = Math.min(best, c);
        }
        return best;
    }
}

