var minimumCost = function(nums) {
    const pals = new Set();
    for (let h = 1; h < 100000; h++) {
        const s = String(h), r = [...s].reverse().join('');
        const p1 = Number(s + r), p2 = Number(s + r.slice(1));
        if (p1 < 1e9) pals.add(p1);
        if (p2 < 1e9) pals.add(p2);
    }
    const arr = [...pals].sort((a, b) => a - b);
    nums.sort((a, b) => a - b);
    const m = nums[Math.floor(nums.length / 2)];
    let i = arr.findIndex(p => p >= m); if (i < 0) i = arr.length;
    let best = Infinity;
    for (let k = Math.max(0, i - 2); k < Math.min(arr.length, i + 2); k++) {
        let c = 0;
        for (const x of nums) c += Math.abs(x - arr[k]);
        best = Math.min(best, c);
    }
    return best;
};
